(* [comment removed for export] *)
Ltac vload W q k HBS :=
  lazymatch type of W with bytes_at _ ?mx ?P ?bs =>
    let b := fresh "b" in let N := fresh "N" in let RD := fresh "RD" in let BR := fresh "BR" in
    destruct (win_byte _ _ _ q W ltac:(lia)) as [b N];
    pose proof (zb_range b) as BR; unfold zb in BR;
    pose proof (u8ro_read usegs _ P bs (q - P) b (Z_to_bv 64 q) W N ltac:(lia) ltac:(symmetry; apply wa_of_Z_to_bv; lia)) as RD;
    step; clear RD; change (zxb b) with (Z_to_bv 64 (zb b)); fold (zb b) in BR;
    rewrite HBS in N; replace (Z.to_nat (q - P)) with k in N by lia; cbn [nth_error] in N; injection N as ->
  end.
Ltac vload_s W q k HBS :=
  lazymatch type of W with bytes_at _ ?mx ?P ?bs =>
    let b := fresh "b" in let N := fresh "N" in let RD := fresh "RD" in let BR := fresh "BR" in
    destruct (win_byte _ _ _ q W ltac:(lia)) as [b N];
    pose proof (zb_range b) as BR;
    pose proof (u8ro_read usegs _ P bs (q - P) b (Z_to_bv 64 q) W N ltac:(lia) ltac:(symmetry; apply wa_of_Z_to_bv; lia)) as RD;
    step; clear RD;
    rewrite HBS in N; replace (Z.to_nat (q - P)) with k in N by lia; cbn [nth_error] in N; injection N as ->
  end.

(* [comment removed for export] *)
Ltac call_bcmp L R ls rs :=
  let S := fresh "BS" in
  pose proof bcmp_spec as S;
  unfold bcmp_stmt, memcmp_stmt_at, memcmp_post, memcmp_post_v, P_BCMP in S;
  call (S L R ls rs); [ assumption | assumption | rewrite ?length_litb; cbn; lia | lia | assumption | clear S ].

(* [comment removed for export] *)
Ltac bcmp_litw lit k ls L P sp :=
  let LB := fresh "LB" in let LZ := fresh "LZ" in
  lazymatch goal with MI : mem_inv _ ?mx |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
    destruct (lit mx MI) as [LB LZ] end;
  replace (Z_to_bv 64 k) with (Z_to_bv 64 (Z.of_nat (length ls))) by (f_equal; lia);
  lazymatch type of LB with bytes_at _ _ ?A ?rs =>
    unfold A in LB; lazymatch type of LB with bytes_at _ _ ?A' _ => call_bcmp L A' ls rs end end;
  (* [comment removed for export] *)
  try match goal with H : bytes_at _ _ L _, H' : bytes_at _ _ L _ |- _ => clear H' end;
  try match goal with H : bytes_at _ _ ?a (litb _), H' : bytes_at _ _ ?a (litb _) |- _ => clear H' end;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
    lazymatch goal with C : verb_ctx ?m0 _ _ _ _ _ _ _ _ _ |- _ => verb_rebuild_ctx m0 sp P end end;
  (* [comment removed for export] *)
  step;
  lazymatch goal with |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
    rewrite (bcmp_branch ls) by (rewrite length_litb; cbn; lia); rewrite LZ end.
Ltac bcmp_lit lit k rest P sp := bcmp_litw lit k rest (P + 1) P sp.
